+const reloadStatusFilename = "reload-status.json"
+
+// transactionalReloadManager tracks the configuration to restore and the last
+// complete reload outcome. Its state file deliberately does not contain config.
+type transactionalReloadManager struct {
+	enabled bool
+	path    string
+	logger  *slog.Logger
+
+	mu            sync.RWMutex
+	lastKnownGood *config.Config
+	status        api_v1.ReloadStatus
+}
+
+func newTransactionalReloadManager(enabled bool, dir string, logger *slog.Logger) *transactionalReloadManager {
+	m := &transactionalReloadManager{enabled: enabled, path: filepath.Join(dir, reloadStatusFilename), logger: logger}
+	if enabled {
+		m.load()
+	}
+	return m
+}
+
+func (m *transactionalReloadManager) Enabled() bool { return m.enabled }
+
+func (m *transactionalReloadManager) Status() api_v1.ReloadStatus {
+	m.mu.RLock()
+	defer m.mu.RUnlock()
+	return m.status
+}
+
+func (m *transactionalReloadManager) SetLastKnownGood(conf *config.Config) {
+	m.mu.Lock()
+	defer m.mu.Unlock()
+	m.lastKnownGood = conf
+}
+
+func (m *transactionalReloadManager) RecordLoadError(err error) {
+	if !m.enabled {
+		return
+	}
+	m.record(api_v1.ReloadStatus{
+		LastReloadID:         time.Now().UTC().Format(time.RFC3339Nano),
+		LastReloadSuccessful: false,
+		ErrorCategory:        api_v1.ReloadErrorLoad,
+		ErrorMessage:         err.Error(),
+		AppliedReloaders:     []string{},
+		ReloaderTimingsMS:    map[string]int64{},
+	})
+}
+
+func (m *transactionalReloadManager) Apply(conf *config.Config, reloaders []reloader) error {
+	if !m.enabled {
+		return nil
+	}
+
+	outcome := api_v1.ReloadStatus{
+		LastReloadID:      time.Now().UTC().Format(time.RFC3339Nano),
+		ErrorCategory:     api_v1.ReloadErrorNone,
+		AppliedReloaders:  []string{},
+		ReloaderTimingsMS: map[string]int64{},
+	}
+	for _, rl := range reloaders {
+		start := time.Now()
+		err := rl.reloader(conf)
+		outcome.ReloaderTimingsMS[rl.name] = time.Since(start).Milliseconds()
+		if err == nil {
+			outcome.AppliedReloaders = append(outcome.AppliedReloaders, rl.name)
+			continue
+		}
+
+		outcome.ErrorCategory = api_v1.ReloadErrorApply
+		outcome.ErrorMessage = err.Error()
+		outcome.FailedReloader = rl.name
+		if len(outcome.AppliedReloaders) > 0 {
+			outcome.RollbackAttempted = true
+			outcome.RollbackSuccessful = m.rollback(reloaders)
+			if !outcome.RollbackSuccessful {
+				outcome.ErrorCategory = api_v1.ReloadErrorRollback
+			}
+		}
+		m.record(outcome)
+		return fmt.Errorf("failed to apply configuration with reloader %q: %w", rl.name, err)
+	}
+
+	outcome.LastReloadSuccessful = true
+	m.SetLastKnownGood(conf)
+	m.record(outcome)
+	return nil
+}
+
+func (m *transactionalReloadManager) rollback(reloaders []reloader) bool {
+	m.mu.RLock()
+	conf := m.lastKnownGood
+	m.mu.RUnlock()
+	if conf == nil {
+		return false
+	}
+	for _, rl := range reloaders {
+		if err := rl.reloader(conf); err != nil {
+			m.logger.Error("Failed to roll back configuration", "reloader", rl.name, "err", err)
+			return false
+		}
+	}
+	return true
+}
+
+func (m *transactionalReloadManager) record(status api_v1.ReloadStatus) {
+	m.mu.Lock()
+	m.status = status
+	m.mu.Unlock()
+
+	data, err := json.Marshal(status)
+	if err != nil {
+		m.logger.Error("Failed to marshal transactional reload status", "err", err)
+		return
+	}
+	if err := os.MkdirAll(filepath.Dir(m.path), 0o755); err != nil {
+		m.logger.Error("Failed to create transactional reload status directory", "err", err)
+		return
+	}
+	tmp := m.path + ".tmp"
+	if err := os.WriteFile(tmp, data, 0o600); err == nil {
+		err = os.Rename(tmp, m.path)
+	}
+	if err != nil {
+		m.logger.Error("Failed to persist transactional reload status", "err", err)
+	}
+}
+
+func (m *transactionalReloadManager) load() {
+	data, err := os.ReadFile(m.path)
+	if err != nil {
+		if !os.IsNotExist(err) {
+			m.logger.Warn("Failed to read transactional reload status", "err", err)
+		}
+		return
+	}
+	var status api_v1.ReloadStatus
+	if err := json.Unmarshal(data, &status); err != nil {
+		m.logger.Warn("Ignoring corrupted transactional reload status", "err", err)
+		return
+	}
+	m.status = status
+}
